import os, sys, json, subprocess, hashlib

def run_cmd(cmd):
    p = subprocess.run(cmd, capture_output=True, text=True)
    if p.returncode != 0:
        print("STDOUT:", p.stdout)
        print("STDERR:", p.stderr)
        raise SystemExit(p.returncode)
    s = p.stdout.strip()
    try:
        return json.loads(s)
    except Exception:
        return {"raw": s}

# 1) Write minimal config (no data; tolerance verify on metrics)
cfg = {
    "env": {"python": "3.10", "deps": []},
    "data": [],
    "entrypoint": [
        sys.executable, "-c",
        "import json,os; os.makedirs('outputs',exist_ok=True); "
        "json.dump({'accuracy':0.8123}, open('outputs/metrics.json','w')); "
        "open('outputs/table.csv','w').write('a,b\\n1,2\\n')"
    ],
    "outputs": [
        {
            "path": "outputs/metrics.json",
            "metrics": {
                "accuracy": {"mode": "tolerance", "target": 0.8123, "atol": 1e-9, "rtol": 1e-9}
            }
        },
        {"path": "outputs/table.csv"}
    ]
}
with open("verify_config.json", "w", encoding="utf-8") as f:
    json.dump(cfg, f, indent=2, ensure_ascii=False)

# 2) Preflight (static checks)
pref = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/preflight_static.py",
                "--config", "verify_config.json"])

# 3) Run (env capture, optional entrypoint execution)
run_out = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/run.py",
                   "--config", "verify_config.json", "--cwd", "."])

# 4) Verify with tolerance
ver_tol = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/verify.py",
                   "--mode", "with-tolerance", "--config", "verify_config.json"])

# 5) Build strict config with computed SHA256s, then verify strict
def sha256(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        h.update(f.read())
    return h.hexdigest()

strict_cfg = cfg.copy()
strict_outputs = []
for out in cfg["outputs"]:
    o2 = dict(out)
    if os.path.exists(o2["path"]):
        o2["sha256"] = sha256(o2["path"])
    strict_outputs.append(o2)
strict_cfg["outputs"] = strict_outputs
with open("verify_config.strict.json", "w", encoding="utf-8") as f:
    json.dump(strict_cfg, f, indent=2, ensure_ascii=False)

ver_strict = run_cmd([sys.executable, "storage/shared/agency_lab/repro_template/v2/verify.py",
                      "--mode", "strict", "--config", "verify_config.strict.json"])

print(json.dumps({
    "preflight": pref,
    "run": run_out,
    "verify_tolerance": ver_tol,
    "verify_strict": ver_strict
}, indent=2, ensure_ascii=False))

